Below is the core architecture and representative source code for the **EduLearn Hub** Web-based Learning System developed using ASP.NET Web Forms (.NET Framework) and SQL Server LocalDB.

### File Organization
- `/App_Data/EduLearnDB.mdf` (Local Database)
- `/CSS/styles.css` (External stylesheet)
- `/MasterPage.master` (Navigation and HTML5 layout)
- `Default.aspx`, `Register.aspx`, `Login.aspx`
- `/Member/Dashboard.aspx`, `/Member/SelfAssessment.aspx`
- `/Admin/ManageResources.aspx` (CRUD Operations)

### 1. External CSS (`/CSS/styles.css`)
```css
body { font-family: Arial, sans-serif; margin: 0; background-color: #f4f7f6; }
header, nav, section, footer { display: block; }
nav { background: #2c3e50; padding: 10px; }
nav a { color: white; margin-right: 15px; text-decoration: none; font-weight: bold; }
.container { width: 85%; margin: auto; padding: 20px; background: white; }
```

### 2. Registration & Form Validation (`Register.aspx`)
Demonstrates HTML5 semantic tags, internal/inline CSS, and ASP.NET validation controls.
```html
<%@ Page Title="Register" Language="C#" MasterPageFile="~/MasterPage.master" AutoEventWireup="true" CodeBehind="Register.aspx.cs" Inherits="EduLearn.Register" %>
<asp:Content ID="Content1" ContentPlaceHolderID="MainContent" runat="server">
    <style>.error { color: red; font-size: 12px; }</style>
    <section class="container">
        <h2 style="color: #2c3e50;">New Member Registration</h2>
        <article>
            <label>Username:</label>
            <asp:TextBox ID="txtUsername" runat="server"></asp:TextBox>
            <asp:RequiredFieldValidator ID="rfvUser" runat="server" ControlToValidate="txtUsername" ErrorMessage="Username is required" CssClass="error" />
            <br /><br />
            <label>Email:</label>
            <asp:TextBox ID="txtEmail" runat="server" TextMode="Email"></asp:TextBox>
            <asp:RegularExpressionValidator ID="revEmail" runat="server" ControlToValidate="txtEmail" ErrorMessage="Invalid Email" ValidationExpression="\w+([-+.']\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*" CssClass="error" />
            <br /><br />
            <label>Password:</label>
            <asp:TextBox ID="txtPass" runat="server" TextMode="Password"></asp:TextBox>
            <br /><br />
            <asp:Button ID="btnRegister" runat="server" Text="Register" OnClick="btnRegister_Click" />
        </article>
    </section>
</asp:Content>
```

### 3. Admin CRUD & Database Connectivity (`ManageResources.aspx.cs`)
Demonstrates Insert, Select, Update, and Delete operations for learning resources.
```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.Configuration;

namespace EduLearn.Admin {
    public partial class ManageResources : System.Web.UI.Page {
        string connStr = ConfigurationManager.ConnectionStrings["EduLearnDB"].ConnectionString;

        protected void Page_Load(object sender, EventArgs e) {
            if (Session["Role"]?.ToString() != "Admin") Response.Redirect("~/Login.aspx");
            if (!IsPostBack) BindGrid();
        }

        void BindGrid() {
            using (SqlConnection con = new SqlConnection(connStr)) {
                SqlDataAdapter sda = new SqlDataAdapter("SELECT * FROM Resources", con);
                DataTable dt = new DataTable();
                sda.Fill(dt);
                gvResources.DataSource = dt;
                gvResources.DataBind();
            }
        }

        protected void btnInsert_Click(object sender, EventArgs e) {
            using (SqlConnection con = new SqlConnection(connStr)) {
                string query = "INSERT INTO Resources (Title, Category, VideoUrl) VALUES (@Title, @Cat, @Url)";
                SqlCommand cmd = new SqlCommand(query, con);
                cmd.Parameters.AddWithValue("@Title", txtTitle.Text);
                cmd.Parameters.AddWithValue("@Cat", ddlCategory.SelectedValue);
                cmd.Parameters.AddWithValue("@Url", txtUrl.Text);
                con.Open(); cmd.ExecuteNonQuery();
            }
            BindGrid();
        }

        protected void btnUpdate_Click(object sender, EventArgs e) {
            using (SqlConnection con = new SqlConnection(connStr)) {
                string query = "UPDATE Resources SET Title=@Title, Category=@Cat WHERE ResourceID=@ID";
                SqlCommand cmd = new SqlCommand(query, con);
                cmd.Parameters.AddWithValue("@ID", txtID.Text);
                cmd.Parameters.AddWithValue("@Title", txtTitle.Text);
                cmd.Parameters.AddWithValue("@Cat", ddlCategory.SelectedValue);
                con.Open(); cmd.ExecuteNonQuery();
            }
            BindGrid();
        }

        protected void btnDelete_Click(object sender, EventArgs e) {
            using (SqlConnection con = new SqlConnection(connStr)) {
                SqlCommand cmd = new SqlCommand("DELETE FROM Resources WHERE ResourceID=@ID", con);
                cmd.Parameters.AddWithValue("@ID", txtID.Text);
                con.Open(); cmd.ExecuteNonQuery();
            }
            BindGrid();
        }
    }
}
```
